/* PsychLogic — Foundational Mock 7 (Neuropsychology & Disorders) question bank.
   Each item: { id, question, options[4], correctAnswer(0-3), subject, explanation, examWatch (PsychLogic Insight) } */
window.MOCK_QUESTIONS = [{"id": 1, "question": "Which is a Schneiderian First Rank Symptom?", "options": ["Auditory hallucinations commenting on one's actions", "Depersonalization", "Phobia", "Obsessive thoughts"], "correctAnswer": 0, "subject": "Descriptive Psychopathology & Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Schneider&#x27;s first-rank symptoms are specific psychotic experiences — voices commenting on one&#x27;s actions, voices arguing, audible thoughts, thought insertion/withdrawal/broadcasting, made experiences and delusional perception. &#x27;Voices commenting on your actions&#x27; is a classic one.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Depersonalization is a dissociative experience, not a first-rank symptom.</li><li><b>C —</b> Phobia is an anxiety symptom.</li><li><b>D —</b> Obsessive thoughts belong to OCD, not psychosis.</li></ul><div class=\"ex-sub\">Remember</div><p>First-rank symptoms = Schneider&#x27;s list of &#x27;core&#x27; psychotic experiences (voices, thought alienation, passivity, delusional perception).</p>", "examWatch": "As per PsychLogic's analysis: A perennial favourite — be able to list Schneider&#x27;s first-rank symptoms and tell them apart from dissociative and anxiety symptoms, which examiners love to slip in as distractors."}, {"id": 2, "question": "Phineas Gage, who survived an iron rod passing through his skull in 1848, showed marked personality change mainly because of damage to the:", "options": ["Left inferior frontal gyrus", "Dorsolateral prefrontal cortex", "Anterior temporal pole", "Ventromedial prefrontal cortex"], "correctAnswer": 3, "subject": "Frontal & Lesion Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> Phineas Gage&#x27;s rod damaged the ventromedial/orbitofrontal prefrontal cortex, which governs emotion, judgement and social behaviour — so his personality changed while memory, language and movement stayed intact.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> The left inferior frontal gyrus is Broca&#x27;s area (speech production).</li><li><b>B —</b> Dorsolateral PFC damage causes a dysexecutive, not mainly a personality, syndrome.</li><li><b>C —</b> The anterior temporal pole relates to semantic memory.</li></ul><div class=\"ex-sub\">Remember</div><p>Gage → ventromedial/orbitofrontal PFC → personality, emotion and social judgement.</p>", "examWatch": "As per PsychLogic's analysis: Phineas Gage is a guaranteed name to know — link the lesion (ventromedial/orbitofrontal) to personality and decision-making, and don&#x27;t confuse it with dorsolateral (dysexecutive) damage."}, {"id": 3, "question": "After bilateral medial temporal lobectomy, patient H.M. (studied by Brenda Milner) could still learn which of the following?", "options": ["Mirror-drawing skill", "New facts about current events", "New vocabulary words", "Faces of new hospital staff"], "correctAnswer": 0, "subject": "Memory & Amnesia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> H.M. lost the ability to form new conscious (declarative) memories after his hippocampi were removed, but could still learn motor skills like mirror-drawing — proving procedural memory is a separate system.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> New facts are semantic/declarative memory — impaired in H.M.</li><li><b>C —</b> Learning new words is declarative — impaired.</li><li><b>D —</b> Recognising new faces needs new declarative memory — impaired.</li></ul><div class=\"ex-sub\">Remember</div><p>H.M. → intact procedural (skill) memory, lost declarative memory → the two systems are separate.</p>", "examWatch": "As per PsychLogic's analysis: H.M. is a landmark case; the key exam point is the dissociation between intact procedural learning and lost declarative memory. Expect it framed as a scenario."}, {"id": 4, "question": "The typical resting membrane potential of a neuron is approximately:", "options": ["+70 mV", "–70 mV", "0 mV", "+30 mV"], "correctAnswer": 1, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> A neuron at rest sits at about –70 mV: the inside is negative relative to the outside, maintained by ion gradients and the sodium–potassium pump.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> +70 mV is the wrong sign (inside is negative).</li><li><b>C —</b> 0 mV would mean no charge separation.</li><li><b>D —</b> +30 mV is near the peak of an action potential, not rest.</li></ul><div class=\"ex-sub\">Remember</div><p>Resting potential ≈ –70 mV (inside negative); action-potential peak ≈ +30 mV.</p>", "examWatch": "As per PsychLogic's analysis: A pure fact worth locking in: resting potential ≈ –70 mV. Pair it with the action-potential peak (+30 mV) and the Na⁺/K⁺ pump."}, {"id": 5, "question": "Intellectual Disability (Intellectual Developmental Disorder) is characterized by deficits in:", "options": ["Memory, attention, and perception", "Intellectual functioning and adaptive functioning", "Personality and emotional functioning", "Sensory and motor functioning"], "correctAnswer": 1, "subject": "Neurodevelopmental & Genetic", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Intellectual Disability is defined by deficits in BOTH intellectual functioning (reasoning, problem-solving) AND adaptive functioning (everyday conceptual, social, practical skills), beginning in the developmental period.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Memory/attention/perception alone describe other cognitive disorders.</li><li><b>C —</b> Personality/emotional deficits are not the defining criterion.</li><li><b>D —</b> Sensory/motor deficits are separate.</li></ul><div class=\"ex-sub\">Remember</div><p>ID = intellectual deficits + adaptive deficits, onset in the developmental period.</p>", "examWatch": "As per PsychLogic's analysis: Know the two-part definition of Intellectual Disability (intellectual + adaptive deficits, developmental onset) — examiners test the &#x27;adaptive functioning&#x27; half specifically."}, {"id": 6, "question": "Which pairing is correctly matched?", "options": ["Prader-Willi — hyperphagia", "Angelman — hyperphagia as the defining feature", "Rett — trisomy 21", "Down syndrome — MECP2 mutation"], "correctAnswer": 0, "subject": "Neurodevelopmental & Genetic", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Prader–Willi syndrome is correctly paired with hyperphagia (insatiable appetite and obesity), alongside hypotonia and learning difficulty.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Angelman&#x27;s defining features are severe delay, ataxia and a happy demeanour — not hyperphagia.</li><li><b>C —</b> Rett syndrome is MECP2-related, not trisomy 21.</li><li><b>D —</b> Down syndrome is trisomy 21, not MECP2.</li></ul><div class=\"ex-sub\">Remember</div><p>Prader–Willi = hyperphagia/obesity; Angelman = &#x27;happy puppet&#x27;; Rett = MECP2; Down = trisomy 21.</p>", "examWatch": "As per PsychLogic's analysis: Genetic-syndrome pairings (Prader–Willi, Angelman, Rett, Down) are high-yield and frequently muddled — memorise one defining feature and the genetic cause for each."}, {"id": 7, "question": "A 72-year-old man has gradually developed difficulty managing finances, planning his daily activities, and switching between tasks. His basic language and orientation are relatively preserved. Which cognitive domain is most prominently affected?", "options": ["Episodic memory", "Executive functioning", "Auditory perception", "Procedural memory"], "correctAnswer": 1, "subject": "Attention & Executive Function", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Managing finances, planning, and switching between tasks are executive functions (prefrontal). With language and orientation preserved, the deficit is executive, not a primary memory or language problem.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Episodic memory loss would show as forgetting recent events.</li><li><b>C —</b> Auditory perception is unrelated to planning.</li><li><b>D —</b> Procedural memory is skill learning, intact here.</li></ul><div class=\"ex-sub\">Remember</div><p>Planning, organising and set-switching = executive functions (frontal lobes).</p>", "examWatch": "As per PsychLogic's analysis: Classic &#x27;localise the deficit&#x27; scenario — planning/finances/task-switching = executive (frontal). Practise mapping everyday descriptions onto cognitive domains."}, {"id": 8, "question": "A psychological model proposing that biological vulnerability interacts with environmental stress is the:", "options": ["Diathesis–stress model", "Drive reduction model", "Opponent-process model", "Two-factor theory"], "correctAnswer": 0, "subject": "Descriptive Psychopathology & Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> The diathesis–stress model says a disorder emerges when an underlying vulnerability (diathesis) meets environmental stress — neither alone is usually enough.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Drive reduction is a motivation theory.</li><li><b>C —</b> Opponent-process explains emotion/addiction dynamics.</li><li><b>D —</b> Two-factor theory explains how phobias are learned and maintained.</li></ul><div class=\"ex-sub\">Remember</div><p>Diathesis (vulnerability) × Stress (trigger) → disorder.</p>", "examWatch": "As per PsychLogic's analysis: The diathesis–stress model is a core framework across clinical psychology — be ready to apply it, and to contrast it with purely biological or purely learning models."}, {"id": 9, "question": "Which hormone is most strongly associated with increased aggression, particularly in relation to dominance and competitive behavior?", "options": ["Melatonin", "Oxytocin", "Testosterone", "Insulin"], "correctAnswer": 2, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Testosterone is the androgen most linked to aggression, dominance and competitive behaviour — though the link is shaped by context and learning, not automatic.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Melatonin regulates sleep.</li><li><b>B —</b> Oxytocin supports bonding and trust.</li><li><b>D —</b> Insulin regulates blood glucose.</li></ul><div class=\"ex-sub\">Remember</div><p>Testosterone ↔ dominance/aggression (context-dependent, not deterministic).</p>", "examWatch": "As per PsychLogic's analysis: Hormone–behaviour links are testable; testosterone↔aggression is the headline, but note the exam-safe caveat that the relationship is context-dependent."}, {"id": 10, "question": "Match the following: Syndromes and Clinical Features<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Column I</th><th>Column II</th></tr></thead><tbody><tr><td>1. Diogenes syndrome</td><td>a. Religious or psychotic experiences associated with a particular holy city</td></tr><tr><td>2. Paris syndrome</td><td>b. Psychological reactions associated with intense exposure to artwork</td></tr><tr><td>3. Stendhal syndrome</td><td>c. Severe domestic squalor, self-neglect, and accumulation of possessions</td></tr><tr><td>4. Jerusalem syndrome</td><td>d. Psychological distress occurring when idealized expectations of a city conflict with reality</td></tr></tbody></table></div>", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-b, 2-a, 3-d, 4-c", "1-a, 2-b, 3-c, 4-d"], "correctAnswer": 0, "subject": "Named Clinical Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Diogenes = severe domestic squalor and hoarding (c); Paris = distress when an idealised city clashes with reality (d); Stendhal = overwhelming reaction to great artwork (b); Jerusalem = religious/psychotic experiences in that holy city (a) → 1-c, 2-d, 3-b, 4-a.</p><div class=\"ex-sub\">Remember</div><p>City/place syndromes: Diogenes (squalor), Paris (disillusion), Stendhal (art), Jerusalem (religious).</p>", "examWatch": "As per PsychLogic's analysis: &#x27;City/place syndromes&#x27; (Diogenes, Paris, Stendhal, Jerusalem) are a popular match-the-column set — learn them as a cluster, not individually."}, {"id": 11, "question": "Which neurotransmitters are particularly implicated in mood regulation?", "options": ["Norepinephrine and dopamine", "Acetylcholine and glycine only", "GABA and glutamate only", "Histamine and melatonin only"], "correctAnswer": 0, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Among the options, norepinephrine and dopamine are the classic mood-regulating neurotransmitters (energy, motivation, reward) — central to the monoamine theory of depression (with serotonin).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Acetylcholine/glycine are more about muscle and spinal signalling.</li><li><b>C —</b> GABA/glutamate are the main inhibitory/excitatory pair, not the mood answer here.</li><li><b>D —</b> Histamine/melatonin relate to arousal and sleep.</li></ul><div class=\"ex-sub\">Remember</div><p>Monoamines for mood: serotonin, norepinephrine, dopamine.</p>", "examWatch": "As per PsychLogic's analysis: The monoamine hypothesis (serotonin, noradrenaline, dopamine) underlies mood-disorder questions — know which transmitters pair with mood versus anxiety."}, {"id": 12, "question": "Damage to Broca&#x27;s area is most likely to produce:", "options": ["Receptive aphasia", "Expressive aphasia", "Prosopagnosia", "Visual agnosia"], "correctAnswer": 1, "subject": "Language & Aphasia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Broca&#x27;s area (dominant inferior frontal gyrus) drives speech production, so damage gives non-fluent, effortful (expressive) aphasia with comprehension relatively preserved.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Receptive (Wernicke&#x27;s) aphasia comes from temporal, not Broca&#x27;s, damage.</li><li><b>C —</b> Prosopagnosia is face-recognition loss.</li><li><b>D —</b> Visual agnosia is object-recognition loss.</li></ul><div class=\"ex-sub\">Remember</div><p>Broca = speech production → expressive (non-fluent) aphasia.</p>", "examWatch": "As per PsychLogic's analysis: Broca vs Wernicke is tested almost every cycle — anchor Broca = production/expressive, Wernicke = comprehension/receptive, and know their lobes."}, {"id": 13, "question": "In current DSM-5-TR terminology, the condition historically referred to as “mental retardation” is termed:", "options": ["Intellectual Developmental Disorder", "Intellectual Disability", "Specific Learning Disorder", "Neurocognitive Disorder"], "correctAnswer": 1, "subject": "Neurodevelopmental & Genetic", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> DSM-5-TR uses &#x27;Intellectual Disability&#x27;, with &#x27;(Intellectual Developmental Disorder)&#x27; in parentheses — the respectful replacement for the outdated &#x27;mental retardation&#x27;.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Intellectual Developmental Disorder is the ICD-11/parenthetical term, not the primary DSM label asked.</li><li><b>C —</b> Specific Learning Disorder is a different condition.</li><li><b>D —</b> Neurocognitive Disorder covers acquired decline (e.g., dementia).</li></ul><div class=\"ex-sub\">Remember</div><p>DSM-5-TR: Intellectual Disability (Intellectual Developmental Disorder).</p>", "examWatch": "As per PsychLogic's analysis: A terminology update worth knowing precisely: DSM-5-TR says &#x27;Intellectual Disability&#x27;, not the older &#x27;mental retardation&#x27;."}, {"id": 14, "question": "Match the following: Disorders and Their Characteristic Features<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Column I</th><th>Column II</th></tr></thead><tbody><tr><td>1. Pyromania</td><td>a. Persistent and recurrent problematic engagement in gambling</td></tr><tr><td>2. Kleptomania</td><td>b. Recurrent episodes of disproportionate aggressive behavior</td></tr><tr><td>3. Intermittent explosive disorder</td><td>c. Recurrent urge to steal objects despite not needing them</td></tr><tr><td>4. Gambling disorder</td><td>d. Recurrent deliberate fire-setting accompanied by increasing tension</td></tr></tbody></table></div>", "options": ["1-c, 2-d, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-a, 2-b, 3-d, 4-c", "1-b, 2-a, 3-c, 4-d"], "correctAnswer": 1, "subject": "Eating, Feeding & Impulse-Control", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Pyromania = recurrent deliberate fire-setting with tension/relief (d); Kleptomania = urge to steal unneeded objects (c); Intermittent explosive disorder = disproportionate aggressive outbursts (b); Gambling disorder = persistent problematic gambling (a) → 1-d, 2-c, 3-b, 4-a.</p><div class=\"ex-sub\">Remember</div><p>Impulse-control: pyromania (fire), kleptomania (steal), IED (aggression), gambling disorder.</p>", "examWatch": "As per PsychLogic's analysis: Impulse-control disorders (pyromania, kleptomania, IED, gambling) are a compact, examinable set — one line each is enough."}, {"id": 15, "question": "The repetition or prolongation of a visual phenomenon beyond the time limit of the physiological image is:", "options": ["Akinetopsia", "Paraprosopia", "Palinopsia", "Teleopsia"], "correctAnswer": 2, "subject": "Perception & Agnosias", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Palinopsia is the persistence or recurrence of a visual image after the stimulus is gone — a visual perseveration.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Akinetopsia is loss of motion perception.</li><li><b>B —</b> &#x27;Paraprosopia&#x27; is not the right term here (face distortion).</li><li><b>D —</b> Teleopsia is seeing objects as farther away than they are.</li></ul><div class=\"ex-sub\">Remember</div><p>Palinopsia = visual &#x27;after-image&#x27; that persists/repeats.</p>", "examWatch": "As per PsychLogic's analysis: Rare visual phenomena (palinopsia, akinetopsia, teleopsia) are exactly the &#x27;surprise&#x27; vocabulary IHBAS-style papers like — learn the one-word definitions."}, {"id": 16, "question": "Cataplexy refers to:", "options": ["Sudden loss of muscle tone triggered by strong emotions", "Recurrent nightmares", "Difficulty initiating sleep", "Extreme daytime sleepiness and sudden, uncontrollable sleep attacks"], "correctAnswer": 0, "subject": "Sleep & Circadian", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Cataplexy is a sudden, brief loss of muscle tone triggered by strong emotion (laughter, surprise) with consciousness preserved — a hallmark of narcolepsy type 1.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Recurrent nightmares are a parasomnia.</li><li><b>C —</b> Trouble falling asleep is insomnia.</li><li><b>D —</b> Overwhelming daytime sleepiness is the sleepiness of narcolepsy, not cataplexy itself.</li></ul><div class=\"ex-sub\">Remember</div><p>Cataplexy = emotion-triggered muscle-tone loss (narcolepsy); distinct from the sleepiness itself.</p>", "examWatch": "As per PsychLogic's analysis: Cataplexy is the hallmark of narcolepsy type 1 — don&#x27;t confuse it with the daytime sleepiness itself; the &#x27;emotion-triggered&#x27; cue is the giveaway."}, {"id": 17, "question": "Match the neuropsychological domain with its most appropriate description.<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Column I</th><th>Column II</th></tr></thead><tbody><tr><td>A. Sustained attention</td><td>1. Switching between mental sets</td></tr><tr><td>B. Divided attention</td><td>2. Maintaining focus over time</td></tr><tr><td>C. Cognitive flexibility</td><td>3. Processing multiple tasks/information streams</td></tr><tr><td>D. Inhibition</td><td>4. Suppressing a dominant response</td></tr></tbody></table></div>", "options": ["A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-1, B-4, C-2, D-3", "A-4, B-1, C-3, D-2"], "correctAnswer": 0, "subject": "Attention & Executive Function", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Sustained attention = holding focus over time (2); Divided attention = handling multiple streams (3); Cognitive flexibility = switching mental sets (1); Inhibition = suppressing a dominant response (4) → A-2, B-3, C-1, D-4.</p><div class=\"ex-sub\">Remember</div><p>Attention/EF: sustained (over time), divided (multitask), flexibility (switch), inhibition (suppress).</p>", "examWatch": "As per PsychLogic's analysis: Attention/executive-function terminology (sustained, divided, flexibility, inhibition) recurs as match items — know the one-phrase definition of each."}, {"id": 18, "question": "A person experiences hallucinations, perceptual distortions, and synesthesia after taking a drug. The most likely substance is:", "options": ["LSD", "Heroin", "Alcohol", "Cannabis"], "correctAnswer": 0, "subject": "Substance Use", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> LSD is a classic hallucinogen that produces perceptual distortions, vivid hallucinations, altered time sense and synesthesia (blending of senses).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Heroin is an opioid — sedation, not psychedelia.</li><li><b>C —</b> Alcohol is a depressant.</li><li><b>D —</b> Cannabis alters perception but synesthesia is far more characteristic of LSD.</li></ul><div class=\"ex-sub\">Remember</div><p>Synesthesia + vivid perceptual distortion → hallucinogen (LSD).</p>", "examWatch": "As per PsychLogic's analysis: Drug-effect profiles are testable — synesthesia and vivid perceptual distortion point to hallucinogens (LSD). Know the class for each common substance."}, {"id": 19, "question": "In Bulimia nervosa involving recurrent self-induced vomiting, a common electrolyte abnormality is:", "options": ["Hyperkalemia", "Hypokalemia", "Hypercalcemia", "Hypernatremia"], "correctAnswer": 1, "subject": "Eating, Feeding & Impulse-Control", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Repeated self-induced vomiting loses stomach acid and potassium, causing hypokalemia (low potassium) and metabolic alkalosis — dangerous because low potassium can trigger cardiac arrhythmias.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Vomiting lowers, not raises, potassium.</li><li><b>C —</b> Hypercalcemia isn&#x27;t the typical finding.</li><li><b>D —</b> Vomiting tends toward low, not high, sodium.</li></ul><div class=\"ex-sub\">Remember</div><p>Purging → hypokalemia + metabolic alkalosis (arrhythmia risk).</p>", "examWatch": "As per PsychLogic's analysis: Medical complications of eating disorders are high-yield — purging → hypokalemia → arrhythmia risk is the chain to remember."}, {"id": 20, "question": "Match List I (Syndrome/Phenomenon) with List II (Description):<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Anton syndrome</td><td>a. Complex visual hallucinations with preserved insight in visually impaired people</td></tr><tr><td>2. Blindsight</td><td>b. Denial of blindness despite cortical blindness</td></tr><tr><td>3. Charles Bonnet syndrome</td><td>c. Residual visual discrimination without awareness after V1 damage</td></tr><tr><td>4. Balint syndrome</td><td>d. Simultanagnosia, optic ataxia and oculomotor apraxia</td></tr></tbody></table></div>", "options": ["1-c, 2-b, 3-a, 4-d", "1-b, 2-c, 3-d, 4-a", "1-b, 2-c, 3-a, 4-d", "1-a, 2-c, 3-b, 4-d"], "correctAnswer": 2, "subject": "Perception & Agnosias", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Anton = denial of blindness despite cortical blindness (b); Blindsight = residual visual discrimination without awareness after V1 damage (c); Charles Bonnet = complex visual hallucinations with insight in the visually impaired (a); Balint = simultanagnosia + optic ataxia + oculomotor apraxia (d) → 1-b, 2-c, 3-a, 4-d.</p><div class=\"ex-sub\">Remember</div><p>Visual syndromes: Anton (denies blindness), blindsight (sees without awareness), Charles Bonnet (hallucinations + insight), Balint (triad).</p>", "examWatch": "As per PsychLogic's analysis: Cortical visual syndromes (Anton, blindsight, Charles Bonnet, Balint) are a classic neuropsych match set — learn them together."}, {"id": 21, "question": "A person strongly believes that unrelated television programs contain special messages specifically intended for them. This is an example of:", "options": ["Delusion of reference", "Delusion of grandeur", "Thought insertion", "Somatic delusion"], "correctAnswer": 0, "subject": "Descriptive Psychopathology & Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> A delusion of reference is the fixed belief that neutral events — like TV programmes — carry special personal messages meant just for you.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Grandeur = inflated importance/power.</li><li><b>C —</b> Thought insertion = thoughts placed into one&#x27;s mind by others.</li><li><b>D —</b> Somatic delusion = false belief about one&#x27;s body.</li></ul><div class=\"ex-sub\">Remember</div><p>Delusion of reference = &#x27;ordinary things are secretly about me&#x27;.</p>", "examWatch": "As per PsychLogic's analysis: Types of delusion (reference, grandeur, control, somatic) are core descriptive psychopathology — practise identifying them from short vignettes."}, {"id": 22, "question": "A child has characteristic facial features, hypotonia and intellectual disability associated with an extra copy of chromosome 21. The most likely diagnosis is:", "options": ["Turner syndrome", "Down syndrome", "Klinefelter syndrome", "Angelman syndrome"], "correctAnswer": 1, "subject": "Neurodevelopmental & Genetic", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> An extra chromosome 21 (trisomy 21) with characteristic facies, hypotonia and intellectual disability is Down syndrome.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Turner = 45,X (females).</li><li><b>C —</b> Klinefelter = 47,XXY (males).</li><li><b>D —</b> Angelman = chromosome 15/UBE3A, not trisomy 21.</li></ul><div class=\"ex-sub\">Remember</div><p>Trisomy 21 = Down syndrome.</p>", "examWatch": "As per PsychLogic's analysis: Chromosomal syndromes keep appearing — fix trisomy 21 = Down, and keep Turner/Klinefelter/Angelman distinct by their genetics."}, {"id": 23, "question": "The defining feature distinguishing Bipolar I disorder from Bipolar II disorder is the presence of:", "options": ["Hypomania in Bipolar I", "Mania in Bipolar I", "Depression in Bipolar I", "Anxiety in Bipolar II"], "correctAnswer": 1, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Bipolar I is defined by at least one full manic episode. Bipolar II has hypomania + major depression but never full mania.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Hypomania occurs in Bipolar II, not the I-defining feature.</li><li><b>C —</b> Depression occurs in both.</li><li><b>D —</b> Anxiety isn&#x27;t a defining bipolar feature.</li></ul><div class=\"ex-sub\">Remember</div><p>Bipolar I = mania; Bipolar II = hypomania + depression (no full mania).</p>", "examWatch": "As per PsychLogic's analysis: The Bipolar I vs II distinction (mania vs hypomania) is a reliable single-fact question — state it in one line."}, {"id": 24, "question": "Match List I (Researcher) with List II (Contribution):<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Paul Broca</td><td>a. Mass action and equipotentiality</td></tr><tr><td>2. Karl Lashley</td><td>b. Split-brain research</td></tr><tr><td>3. Roger Sperry</td><td>c. Cell assembly (&quot;neurons that fire together wire together&quot;)</td></tr><tr><td>4. Donald Hebb</td><td>d. Speech-production area, from the patient &quot;Tan&quot;</td></tr></tbody></table></div>", "options": ["1-b, 2-a, 3-d, 4-c", "1-d, 2-a, 3-b, 4-c", "1-d, 2-c, 3-b, 4-a", "1-a, 2-d, 3-c, 4-b"], "correctAnswer": 1, "subject": "History & Pioneers", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Broca = speech-production area from patient &#x27;Tan&#x27; (d); Lashley = mass action &amp; equipotentiality (a); Sperry = split-brain research (b); Hebb = cell assembly, &#x27;fire together, wire together&#x27; (c) → 1-d, 2-a, 3-b, 4-c.</p><div class=\"ex-sub\">Remember</div><p>Broca (&#x27;Tan&#x27;), Lashley (mass action), Sperry (split-brain), Hebb (cell assembly).</p>", "examWatch": "As per PsychLogic's analysis: History-of-neuropsychology pioneers (Broca, Lashley, Sperry, Hebb) are a standard match set — one contribution each is enough."}, {"id": 25, "question": "The ventrolateral preoptic nucleus (VLPO) promotes sleep mainly by:", "options": ["Activating the locus coeruleus", "Inhibiting arousal-promoting systems", "Increasing dopamine release", "Activating the motor cortex"], "correctAnswer": 1, "subject": "Sleep & Circadian", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> The VLPO promotes sleep by using inhibitory transmitters (GABA, galanin) to switch OFF the arousal systems (locus coeruleus, raphe, TMN) — the &#x27;off switch&#x27; of the sleep–wake flip-flop.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> It inhibits, not activates, the locus coeruleus.</li><li><b>C —</b> It isn&#x27;t primarily a dopamine system.</li><li><b>D —</b> It doesn&#x27;t activate motor cortex.</li></ul><div class=\"ex-sub\">Remember</div><p>VLPO = sleep &#x27;off-switch&#x27; → inhibits arousal centres (GABA/galanin).</p>", "examWatch": "As per PsychLogic's analysis: The VLPO &#x27;sleep switch&#x27; and reciprocal inhibition of arousal centres is a neat, examinable mechanism — know it as the sleep &#x27;off-switch&#x27;."}, {"id": 26, "question": "Arrange the following according to increasing complexity of attention: Sustained attention Divided attention Simple attention Selective attention", "options": ["3 → 1 → 4 → 2", "1 → 3 → 2 → 4", "4 → 2 → 1 → 3", "3 → 4 → 1 → 2"], "correctAnswer": 0, "subject": "Attention & Executive Function", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> From least to most complex: Simple (3) → Sustained (1) → Selective (4) → Divided (2). Simple reacts; sustained holds focus; selective filters; divided juggles several streams → 3 → 1 → 4 → 2.</p><div class=\"ex-sub\">Remember</div><p>Attention complexity: simple &lt; sustained &lt; selective &lt; divided.</p>", "examWatch": "As per PsychLogic's analysis: Ordering/sequence items on attention complexity test understanding, not recall — reason from simple → divided rather than memorising."}, {"id": 27, "question": "A patient firmly believes that they are infested with parasites despite medical evidence to the contrary. This syndrome is commonly called:", "options": ["Othello syndrome", "Ekbom syndrome", "Dat syndrome", "Ganser syndrome"], "correctAnswer": 1, "subject": "Named Clinical Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Ekbom syndrome (delusional infestation/parasitosis) is the fixed belief of being infested with parasites despite no medical evidence.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Othello = delusional jealousy.</li><li><b>C —</b> &#x27;Dat&#x27; (Cotard-like) isn&#x27;t the infestation term.</li><li><b>D —</b> Ganser = approximate answers.</li></ul><div class=\"ex-sub\">Remember</div><p>Ekbom = delusional infestation (&#x27;bugs under the skin&#x27;).</p>", "examWatch": "As per PsychLogic's analysis: Named delusional syndromes (Ekbom, Othello, Cotard, Capgras, Ganser) are frequent — build a quick one-line table."}, {"id": 28, "question": "The neurotransmitter that is decreased in anxiety disorders is:", "options": ["Glutamate", "Gamma amino butyric' acid", "Serotonin", "Acetylcholine"], "correctAnswer": 1, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> GABA is the brain&#x27;s main inhibitory neurotransmitter; reduced GABA activity means less braking on neurons → excess excitability, tension and anxiety. Benzodiazepines work by boosting GABA.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Glutamate is excitatory, not the &#x27;decreased inhibitory&#x27; answer.</li><li><b>C —</b> Serotonin is involved but isn&#x27;t the inhibitory transmitter asked.</li><li><b>D —</b> Acetylcholine relates to memory/muscle.</li></ul><div class=\"ex-sub\">Remember</div><p>Low GABA (main inhibitory transmitter) ↔ anxiety; benzodiazepines enhance GABA-A.</p>", "examWatch": "As per PsychLogic's analysis: GABA = main inhibitory transmitter, low in anxiety, boosted by benzodiazepines — a high-yield chain across pharmacology questions."}, {"id": 29, "question": "Arrange the components of the Papez circuit in the correct sequence of information flow: Fornix Mammillary bodies Hippocampus Anterior thalamic nucleus", "options": ["3-2-1-4", "1-3-2-4", "3-1-4-2", "3-1-2-4"], "correctAnswer": 3, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> Papez flow: Hippocampus (3) → Fornix (1) → Mammillary bodies (2) → Anterior thalamic nucleus (4) → 3-1-2-4.</p><div class=\"ex-sub\">Remember</div><p>Papez: hippocampus → fornix → mammillary bodies → anterior thalamus → cingulate → back.</p>", "examWatch": "As per PsychLogic's analysis: The Papez circuit sequence is a favourite ordering item — memorise hippocampus → fornix → mammillary bodies → anterior thalamus."}, {"id": 30, "question": "The sympathetic nervous system is associated with:", "options": ["Rest-and-digest responses", "Fight-or-flight responses", "Voluntary skeletal movement", "Language comprehension"], "correctAnswer": 1, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> The sympathetic nervous system drives &#x27;fight-or-flight&#x27;: faster heart rate, mobilised glucose, dilated airways, blood to muscles.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Rest-and-digest is the parasympathetic system.</li><li><b>C —</b> Voluntary movement is the somatic system.</li><li><b>D —</b> Language is cortical.</li></ul><div class=\"ex-sub\">Remember</div><p>Sympathetic = fight-or-flight; parasympathetic = rest-and-digest.</p>", "examWatch": "As per PsychLogic's analysis: Sympathetic vs parasympathetic (fight-or-flight vs rest-and-digest) is basic but frequently tested — know the autonomic split cold."}, {"id": 31, "question": "A person intentionally produces illness symptoms primarily to assume the sick role, without obvious external incentives. This is:", "options": ["Malingering", "Factitious disorder", "Somatic symptom disorder", "Conversion disorder"], "correctAnswer": 1, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Factitious disorder = intentionally producing or faking illness to take on the &#x27;sick role&#x27;, with NO external reward.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Malingering fakes illness for external gain (money, avoiding duty).</li><li><b>C —</b> Somatic symptom disorder = genuine distress about real symptoms, not faked.</li><li><b>D —</b> Conversion = unintentional neurological-type symptoms.</li></ul><div class=\"ex-sub\">Remember</div><p>Factitious = sick role (internal motive); malingering = external gain.</p>", "examWatch": "As per PsychLogic's analysis: Factitious disorder vs malingering turns on motive (sick role vs external gain) — this exact contrast is a repeat question."}, {"id": 32, "question": "Match the following: Personality Disorders and Clinical Features<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Column I</th><th>Column II</th></tr></thead><tbody><tr><td>1. Narcissistic personality disorder</td><td>a. Persistent suspiciousness and difficulty trusting others</td></tr><tr><td>2. Histrionic personality disorder</td><td>b. Limited interest in close relationships and social detachment</td></tr><tr><td>3. Schizoid personality disorder</td><td>c. Strong need for recognition accompanied by grandiose self-perception</td></tr><tr><td>4. Paranoid personality disorder</td><td>d. Marked emotionality and a strong desire for attention</td></tr></tbody></table></div>", "options": ["1-c, 2-d, 3-b, 4-a", "1-a, 2-c, 3-d, 4-b", "1-d, 2-b, 3-a, 4-c", "1-b, 2-a, 3-c, 4-d"], "correctAnswer": 0, "subject": "Descriptive Psychopathology & Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Narcissistic = grandiosity + need for admiration (c); Histrionic = marked emotionality + attention-seeking (d); Schizoid = detachment, little interest in relationships (b); Paranoid = pervasive suspiciousness (a) → 1-c, 2-d, 3-b, 4-a.</p><div class=\"ex-sub\">Remember</div><p>Narcissistic (grandiose), Histrionic (dramatic), Schizoid (detached), Paranoid (suspicious).</p>", "examWatch": "As per PsychLogic's analysis: Cluster A/B/C personality-disorder features are heavily tested — this match set rewards knowing one defining trait per disorder."}, {"id": 33, "question": "A fixed false belief that one&#x27;s partner is unfaithful despite lack of evidence is called:", "options": ["Capgras syndrome", "Othello syndrome", "Cotard syndrome", "Ganser syndrome"], "correctAnswer": 1, "subject": "Named Clinical Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Othello syndrome is the delusional, fixed belief that one&#x27;s partner is unfaithful despite no real evidence — pathological jealousy.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Capgras = &#x27;an impostor has replaced someone I know&#x27;.</li><li><b>C —</b> Cotard = nihilistic delusion (being dead/not existing).</li><li><b>D —</b> Ganser = approximate answers.</li></ul><div class=\"ex-sub\">Remember</div><p>Othello = delusional jealousy of a partner.</p>", "examWatch": "As per PsychLogic's analysis: Othello (jealousy) sits in the named-delusion family — pair it with Capgras, Cotard and De Clérambault so you don&#x27;t mix them up."}, {"id": 34, "question": "La belle indifférence refers to:", "options": ["Unusual lack of concern about a significant neurological-like symptom", "Extreme fear of illness", "Excessive concern about appearance", "Emotional instability in borderline personality disorder"], "correctAnswer": 0, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> La belle indifférence is a striking lack of concern about a serious-seeming neurological symptom, classically linked to conversion disorder (but not diagnostic).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Extreme fear of illness is illness anxiety disorder.</li><li><b>C —</b> Excessive concern about appearance is body dysmorphic disorder.</li><li><b>D —</b> Emotional instability describes borderline PD.</li></ul><div class=\"ex-sub\">Remember</div><p>La belle indifférence = calm indifference to a dramatic symptom (conversion).</p>", "examWatch": "As per PsychLogic's analysis: La belle indifférence is a classic conversion-disorder term — note it&#x27;s neither sensitive nor specific, a point examiners probe."}, {"id": 35, "question": "Arrange the following brain divisions from most rostral to most caudal:", "options": ["Telencephalon → Diencephalon → Mesencephalon → Metencephalon → Myelencephalon", "Diencephalon → Telencephalon → Mesencephalon → Myelencephalon → Metencephalon", "Mesencephalon → Telencephalon → Diencephalon → Metencephalon → Myelencephalon", "Telencephalon → Mesencephalon → Diencephalon → Myelencephalon → Metencephalon"], "correctAnswer": 0, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Rostral→caudal, the embryonic brain divisions run: Telencephalon → Diencephalon → Mesencephalon → Metencephalon → Myelencephalon (forebrain to medulla).</p><div class=\"ex-sub\">Remember</div><p>Order: Telencephalon, Diencephalon, Mesencephalon, Metencephalon, Myelencephalon.</p>", "examWatch": "As per PsychLogic's analysis: Brain-division order (telencephalon → … → myelencephalon) is a standard sequence item — learn the five in order."}, {"id": 36, "question": "Persistent eating of non-nutritive substances such as chalk or clay is:", "options": ["Rumination disorder", "Pica", "ARFID", "Anorexia nervosa"], "correctAnswer": 1, "subject": "Eating, Feeding & Impulse-Control", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Pica is the persistent eating of non-nutritive, non-food substances (chalk, clay, paper) that is developmentally inappropriate.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Rumination = repeated regurgitation of food.</li><li><b>C —</b> ARFID = avoiding food due to sensory/fear issues, not eating non-food.</li><li><b>D —</b> Anorexia = restriction + low weight.</li></ul><div class=\"ex-sub\">Remember</div><p>Pica = eating non-food substances.</p>", "examWatch": "As per PsychLogic's analysis: Feeding disorders (pica, rumination, ARFID) are compact and examinable — one defining line each."}, {"id": 37, "question": "Which component was added to the Baddeley–Hitch working memory model in 2000 to integrate information from different sources with long-term memory?", "options": ["Episodic buffer", "Phonological loop", "Visuospatial sketchpad", "Central executive"], "correctAnswer": 0, "subject": "Memory & Amnesia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Baddeley added the episodic buffer (2000) to bind information from the phonological loop, visuospatial sketchpad and long-term memory into unified multimodal episodes.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> The phonological loop (verbal store) was in the original model.</li><li><b>C —</b> The visuospatial sketchpad was original.</li><li><b>D —</b> The central executive was original.</li></ul><div class=\"ex-sub\">Remember</div><p>Working memory: central executive + phonological loop + sketchpad + (2000) episodic buffer.</p>", "examWatch": "As per PsychLogic's analysis: The Baddeley working-memory model, and especially the 2000 episodic buffer, is high-yield — know all four components and which was added last."}, {"id": 38, "question": "Which technique records electrical activity of the brain from electrodes placed on the scalp?", "options": ["MRI", "EEG", "PET", "CT"], "correctAnswer": 1, "subject": "Assessment & Neuroimaging", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> EEG records the brain&#x27;s electrical activity directly from scalp electrodes, with excellent temporal (millisecond) resolution.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> MRI images structure using magnetism.</li><li><b>C —</b> PET uses radiotracers for metabolism.</li><li><b>D —</b> CT uses X-rays for structure.</li></ul><div class=\"ex-sub\">Remember</div><p>EEG = scalp electrical activity (great timing, poor localisation).</p>", "examWatch": "As per PsychLogic's analysis: Imaging techniques (EEG, MRI, PET, CT, fMRI) are compared constantly — build a grid of what each measures and its strengths."}, {"id": 39, "question": "Parkinson&#x27;s disease is particularly associated with degeneration of neurons in the:", "options": ["Hippocampus", "Substantia nigra", "Amygdala", "Occipital cortex"], "correctAnswer": 1, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Parkinson&#x27;s disease is degeneration of dopamine neurons in the substantia nigra pars compacta, causing tremor, rigidity and bradykinesia.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Hippocampus → memory (Alzheimer&#x27;s).</li><li><b>C —</b> Amygdala → emotion/fear.</li><li><b>D —</b> Occipital cortex → vision.</li></ul><div class=\"ex-sub\">Remember</div><p>Parkinson&#x27;s = loss of dopamine neurons in the substantia nigra.</p>", "examWatch": "As per PsychLogic's analysis: Substantia nigra ↔ Parkinson&#x27;s (dopamine) is a must-know structure–disease link — expect it paired with basal-ganglia questions."}, {"id": 40, "question": "The characteristic involuntary movements of Huntington&#x27;s disease are called:", "options": ["Tremors", "Chorea", "Tics", "Fasciculations"], "correctAnswer": 1, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Huntington&#x27;s disease causes chorea — involuntary, irregular, rapid, dance-like movements — from caudate/basal-ganglia degeneration.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Resting tremor is typical of Parkinson&#x27;s.</li><li><b>C —</b> Tics are seen in Tourette&#x27;s.</li><li><b>D —</b> Fasciculations are muscle twitches (e.g., motor-neuron disease).</li></ul><div class=\"ex-sub\">Remember</div><p>Huntington&#x27;s = chorea (dance-like movements).</p>", "examWatch": "As per PsychLogic's analysis: Movement-disorder vocabulary (chorea, tremor, tics, dystonia) is testable — Huntington&#x27;s = chorea is the headline."}, {"id": 41, "question": "Recurrent episodes of binge eating accompanied by a sense of lack of control, without regular compensatory behaviors, are characteristic of:", "options": ["Anorexia Nervosa", "Bulimia Nervosa", "Binge-Eating Disorder", "Avoidant/Restrictive Food Intake Disorder"], "correctAnswer": 2, "subject": "Eating, Feeding & Impulse-Control", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Binge-eating disorder = recurrent binges with loss of control but NO regular compensatory behaviour (no purging, fasting or over-exercise).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Anorexia = restriction + low weight.</li><li><b>B —</b> Bulimia requires compensatory behaviours.</li><li><b>D —</b> ARFID = avoidant/restrictive eating without body-image concern.</li></ul><div class=\"ex-sub\">Remember</div><p>BED = binges + loss of control, no compensation (unlike bulimia).</p>", "examWatch": "As per PsychLogic's analysis: Eating-disorder differentials (BED vs bulimia vs anorexia) hinge on compensatory behaviour — that distinction is the exam point."}, {"id": 42, "question": "Which cells produce myelin in the peripheral nervous system?", "options": ["Schwann cells", "Oligodendrocytes", "Astrocytes", "Ependymal cells"], "correctAnswer": 0, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Schwann cells make myelin in the peripheral nervous system (one cell per segment of one axon).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Oligodendrocytes myelinate in the CNS.</li><li><b>C —</b> Astrocytes support/regulate the CNS environment.</li><li><b>D —</b> Ependymal cells line ventricles and help make CSF.</li></ul><div class=\"ex-sub\">Remember</div><p>Myelin: Schwann cells (PNS) vs oligodendrocytes (CNS).</p>", "examWatch": "As per PsychLogic's analysis: Schwann (PNS) vs oligodendrocyte (CNS) myelination is a clean fact that recurs — don&#x27;t swap them."}, {"id": 43, "question": "A person repeatedly picks at otherwise healthy skin, causing noticeable lesions, and has made several unsuccessful attempts to stop. Which diagnosis is most appropriate?", "options": ["Trichotillomania", "OCD (unwanted compulsive Actions )", "Excoriation Disorder", "Illness Anxiety Disorder"], "correctAnswer": 2, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Excoriation disorder is recurrent skin-picking causing lesions, with repeated failed attempts to stop — an OCD-related (body-focused repetitive) disorder.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Trichotillomania is hair-pulling.</li><li><b>B —</b> OCD involves obsessions + broader compulsions.</li><li><b>D —</b> Illness anxiety disorder is fear of having a disease.</li></ul><div class=\"ex-sub\">Remember</div><p>Excoriation = skin-picking; trichotillomania = hair-pulling (both body-focused repetitive behaviours).</p>", "examWatch": "As per PsychLogic's analysis: Body-focused repetitive behaviours (excoriation, trichotillomania) sit in the OCD-related chapter — know both and their difference."}, {"id": 44, "question": "Which structure acts as a major relay station for sensory information to the cerebral cortex?", "options": ["Thalamus", "Hypothalamus", "Hippocampus", "Medulla"], "correctAnswer": 0, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> The thalamus is the brain&#x27;s great sensory relay: nearly all sensory information (except smell) passes through its nuclei before reaching the cortex.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Hypothalamus controls hormones/homeostasis.</li><li><b>C —</b> Hippocampus is for memory.</li><li><b>D —</b> Medulla controls vital autonomic functions.</li></ul><div class=\"ex-sub\">Remember</div><p>Thalamus = sensory relay to cortex (olfaction is the exception).</p>", "examWatch": "As per PsychLogic's analysis: Thalamus = sensory relay (except smell) is foundational and frequently tested — remember the olfaction exception."}, {"id": 45, "question": "Match the clinical task with the primary function it can place demands upon.<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Task</th><th>Function</th></tr></thead><tbody><tr><td>A. Generating words under a time limit</td><td>1. Cognitive flexibility</td></tr><tr><td>B. Remembering digits while manipulating them</td><td>2. Verbal fluency</td></tr><tr><td>C. Alternating between two response rules</td><td>3. Working memory</td></tr><tr><td>D. Stopping a prepotent response</td><td>4. Inhibition</td></tr></tbody></table></div>", "options": ["A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-1, B-4, C-2, D-3", "A-4, B-1, C-3, D-2"], "correctAnswer": 0, "subject": "Attention & Executive Function", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Generating words against the clock = verbal fluency (2); holding and manipulating digits = working memory (3); alternating between rules = cognitive flexibility (1); stopping a prepotent response = inhibition (4) → A-2, B-3, C-1, D-4.</p><div class=\"ex-sub\">Remember</div><p>Verbal fluency, working memory, flexibility (shifting), inhibition — the core EF tasks.</p>", "examWatch": "As per PsychLogic's analysis: Clinical EF tasks (fluency, working memory, shifting, inhibition) map onto specific functions — a common applied match item."}, {"id": 46, "question": "Match List I (Memory type) with List II (Principal neural structure):<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Priming</td><td>a. Amygdala</td></tr><tr><td>2. Procedural / skill learning</td><td>b. Prefrontal cortex</td></tr><tr><td>3. Emotional conditioning</td><td>c. Striatum / basal ganglia</td></tr><tr><td>4. Working memory</td><td>d. Neocortex</td></tr></tbody></table></div>", "options": ["1-d, 2-a, 3-c, 4-b", "1-c, 2-d, 3-a, 4-b", "1-d, 2-c, 3-a, 4-b", "1-a, 2-c, 3-d, 4-b"], "correctAnswer": 2, "subject": "Memory & Amnesia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Priming → neocortex (d); Procedural/skill learning → striatum/basal ganglia (c); Emotional conditioning → amygdala (a); Working memory → prefrontal cortex (b) → 1-d, 2-c, 3-a, 4-b.</p><div class=\"ex-sub\">Remember</div><p>Memory ↔ structure: priming (neocortex), procedural (striatum), emotional (amygdala), working (PFC).</p>", "examWatch": "As per PsychLogic's analysis: Memory-system ↔ neural-structure mappings are high-yield neuropsychology — learn priming/procedural/emotional/working as a set."}, {"id": 47, "question": "A patient has difficulty naming familiar objects despite preserved general language comprehension. This is:", "options": ["Anomia", "Echolalia", "Neologism", "Dysarthria"], "correctAnswer": 0, "subject": "Language & Aphasia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Anomia is difficulty naming familiar objects despite otherwise preserved comprehension — shown as pauses, circumlocutions or vague fillers.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Echolalia is repeating others&#x27; words.</li><li><b>C —</b> Neologisms are invented words.</li><li><b>D —</b> Dysarthria is slurred speech from motor problems.</li></ul><div class=\"ex-sub\">Remember</div><p>Anomia = word-finding/naming failure with intact comprehension.</p>", "examWatch": "As per PsychLogic's analysis: Language symptom terms (anomia, echolalia, neologism, dysarthria) are vignette-friendly — know each in one line."}, {"id": 48, "question": "Which hormone is secreted primarily during darkness and promotes sleepiness?", "options": ["GABA", "Melatonin", "Thyroxine", "Adrenaline"], "correctAnswer": 1, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Melatonin, from the pineal gland, is released mainly in darkness and signals &#x27;biological night&#x27;, promoting sleepiness.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> GABA is an inhibitory neurotransmitter, not the darkness hormone.</li><li><b>C —</b> Thyroxine regulates metabolism.</li><li><b>D —</b> Adrenaline is an arousal/stress hormone.</li></ul><div class=\"ex-sub\">Remember</div><p>Melatonin = pineal &#x27;darkness hormone&#x27; → sleepiness.</p>", "examWatch": "As per PsychLogic's analysis: Melatonin = pineal &#x27;darkness hormone&#x27; is a reliable fact — link it to the SCN and circadian control."}, {"id": 49, "question": "The corpus callosum is important because it:", "options": ["Connects the two cerebral hemispheres", "Connects the brain to the spinal cord", "Produces cerebrospinal fluid", "Controls endocrine glands"], "correctAnswer": 0, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> The corpus callosum is the large white-matter bridge connecting the two cerebral hemispheres; cutting it causes split-brain phenomena.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> The brainstem/spinal tracts connect brain to cord.</li><li><b>C —</b> Choroid plexus makes CSF.</li><li><b>D —</b> The pituitary/hypothalamus control endocrine glands.</li></ul><div class=\"ex-sub\">Remember</div><p>Corpus callosum = the bridge between the two hemispheres.</p>", "examWatch": "As per PsychLogic's analysis: The corpus callosum and split-brain phenomena recur together — know its role before tackling split-brain vignettes."}, {"id": 50, "question": "The basal ganglia are particularly involved in:", "options": ["Movement regulation", "Visual perception", "Language comprehension", "Auditory processing"], "correctAnswer": 0, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> The basal ganglia regulate movement — initiation, selection, scaling and habit learning; dysfunction causes Parkinson&#x27;s, Huntington&#x27;s, dystonia and tics.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Vision is occipital.</li><li><b>C —</b> Language is perisylvian cortex.</li><li><b>D —</b> Audition is temporal.</li></ul><div class=\"ex-sub\">Remember</div><p>Basal ganglia = movement regulation + habit learning.</p>", "examWatch": "As per PsychLogic's analysis: Basal ganglia = movement regulation + habit learning, with Parkinson&#x27;s/Huntington&#x27;s as the disease links — a core structure."}, {"id": 51, "question": "A patient irresistibly picks up and uses objects placed before him (a pen, a comb) even when not asked to. This &quot;utilization behaviour&quot; described by Lhermitte is seen in lesions of the:", "options": ["Occipital lobes", "Cerebellar vermis", "Parietal association cortex", "Frontal lobes"], "correctAnswer": 3, "subject": "Frontal & Lesion Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> Utilization behaviour (Lhermitte) — compulsively grabbing and using objects placed in front of you — reflects loss of frontal-lobe inhibitory control.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Occipital lesions cause visual deficits.</li><li><b>B —</b> Cerebellar vermis → balance/gait.</li><li><b>C —</b> Parietal lesions → neglect/visuospatial problems.</li></ul><div class=\"ex-sub\">Remember</div><p>Utilization behaviour = frontal-lobe disinhibition (environmental dependency).</p>", "examWatch": "As per PsychLogic's analysis: Frontal-release/environmental-dependency signs (utilization behaviour) are the kind of named phenomenon IHBAS-style papers test."}, {"id": 52, "question": "Which pair is incorrectly matched?", "options": ["Alice in Wonderland syndrome — perceptual distortions", "Ekbom syndrome — delusional infestation", "Othello syndrome — pathological jealousy", "De Clerambault syndrome — delusional infestation"], "correctAnswer": 3, "subject": "Named Clinical Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> De Clérambault syndrome is erotomania — the delusion that someone (often of higher status) is secretly in love with you. Pairing it with &#x27;delusional infestation&#x27; is wrong (that&#x27;s Ekbom).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Alice in Wonderland → perceptual size/shape distortions (correct).</li><li><b>B —</b> Ekbom → delusional infestation (correct).</li><li><b>C —</b> Othello → pathological jealousy (correct).</li></ul><div class=\"ex-sub\">Remember</div><p>De Clérambault = erotomania (loved by another); Ekbom = infestation.</p>", "examWatch": "As per PsychLogic's analysis: &#x27;Which pair is INCORRECT&#x27; items on named syndromes are common — know De Clérambault = erotomania to catch the trap."}, {"id": 53, "question": "A lesion of the right parietal cortex is particularly associated with:", "options": ["Right-sided neglect", "Left hemispatial neglect", "Expressive aphasia", "Prosopagnosia"], "correctAnswer": 1, "subject": "Frontal & Lesion Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Right parietal damage classically causes LEFT hemispatial neglect — ignoring the left side of space/body — because the right hemisphere handles attention to both sides.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Right-sided neglect is rarer (left parietal).</li><li><b>C —</b> Expressive aphasia is a frontal/left-hemisphere problem.</li><li><b>D —</b> Prosopagnosia is a temporo-occipital face problem.</li></ul><div class=\"ex-sub\">Remember</div><p>Right parietal lesion → left-sided neglect.</p>", "examWatch": "As per PsychLogic's analysis: Right parietal → left neglect is a staple lateralisation fact — reason from &#x27;right hemisphere attends to both sides&#x27;."}, {"id": 54, "question": "A person experiences recurrent episodes of feeling detached from their own thoughts, feelings, or body while remaining aware that the experience is subjective. This is characteristic of:", "options": ["Derealization", "Depersonalization", "Dissociative Amnesia", "Psychosis"], "correctAnswer": 1, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Depersonalization = feeling detached from your own thoughts, feelings or body, while knowing it&#x27;s a subjective experience (reality testing intact).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Derealization is feeling the outside world is unreal.</li><li><b>C —</b> Dissociative amnesia is memory loss.</li><li><b>D —</b> Psychosis involves loss of reality testing.</li></ul><div class=\"ex-sub\">Remember</div><p>Depersonalization (detached from self) vs derealization (world feels unreal).</p>", "examWatch": "As per PsychLogic's analysis: Depersonalization vs derealization is a frequent two-option trap — self vs world is the discriminator."}, {"id": 55, "question": "Which combination is characteristic of Klüver–Bucy syndrome?", "options": ["Hyperorality, hypersexuality, visual agnosia", "Aphasia, paralysis, blindness", "Tremor, rigidity, bradykinesia", "Delusion, hallucination, thought insertion"], "correctAnswer": 0, "subject": "Frontal & Lesion Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Klüver–Bucy syndrome (bilateral anterior temporal/amygdala damage) features hyperorality, hypersexuality, placidity/reduced fear, and visual agnosia (&#x27;psychic blindness&#x27;).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Aphasia/paralysis/blindness is a different lesion pattern.</li><li><b>C —</b> Tremor/rigidity/bradykinesia is parkinsonism.</li><li><b>D —</b> Delusions/hallucinations are psychosis.</li></ul><div class=\"ex-sub\">Remember</div><p>Klüver–Bucy = hyperorality + hypersexuality + placidity + visual agnosia.</p>", "examWatch": "As per PsychLogic's analysis: Klüver–Bucy&#x27;s feature cluster and its bilateral temporal/amygdala basis are classic — learn the full tetrad."}, {"id": 56, "question": "Which technique provides detailed structural images of the brain without using ionizing radiation?", "options": ["MRI", "EEG", "PET", "SPECT"], "correctAnswer": 0, "subject": "Assessment & Neuroimaging", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> MRI gives detailed structural images using magnetic fields and radiofrequency — with NO ionizing radiation (unlike CT, PET, SPECT).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> EEG shows electrical activity, not structure.</li><li><b>C —</b> PET uses radiotracers (radiation).</li><li><b>D —</b> SPECT also uses radiotracers.</li></ul><div class=\"ex-sub\">Remember</div><p>MRI = detailed structure, no ionizing radiation.</p>", "examWatch": "As per PsychLogic's analysis: MRI = structure, no radiation is a constant comparison point against CT/PET/SPECT — know which use ionizing radiation."}, {"id": 57, "question": "A person abruptly travels away from home and cannot recall important autobiographical information. This presentation is most consistent with:", "options": ["Dissociative fugue", "Anterograde amnesia", "Korsakoff syndrome", "Delirium"], "correctAnswer": 0, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Dissociative fugue = sudden, unexpected travel away from home with inability to recall important autobiographical information, often after severe stress.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Anterograde amnesia is failing to form new memories (organic).</li><li><b>C —</b> Korsakoff is thiamine-deficiency amnesia.</li><li><b>D —</b> Delirium is acute fluctuating confusion.</li></ul><div class=\"ex-sub\">Remember</div><p>Fugue = unexpected travel + autobiographical amnesia (dissociative).</p>", "examWatch": "As per PsychLogic's analysis: Dissociative fugue (travel + autobiographical amnesia) is a standard vignette — distinguish it from organic amnesias."}, {"id": 58, "question": "A person is convinced that a famous public figure, whom they have never met, is secretly in love with them. Which condition is most closely associated with this presentation?", "options": ["Othello syndrome", "De Clerambault syndrome", "Ekbom syndrome", "Cotard syndrome"], "correctAnswer": 1, "subject": "Named Clinical Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Believing a celebrity you&#x27;ve never met is secretly in love with you is De Clérambault syndrome (erotomania).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Othello = jealousy delusion.</li><li><b>C —</b> Ekbom = infestation delusion.</li><li><b>D —</b> Cotard = nihilistic delusion.</li></ul><div class=\"ex-sub\">Remember</div><p>Erotomania = De Clérambault (&#x27;they secretly love me&#x27;).</p>", "examWatch": "As per PsychLogic's analysis: Erotomania (De Clérambault), especially about a celebrity, is a repeat named-delusion item — keep it apart from Othello."}, {"id": 59, "question": "A patient fills gaps in memory with plausible but false accounts without conscious intention to deceive. This is called:", "options": ["Perseveration", "Confabulation", "Delusion", "Paramnesia"], "correctAnswer": 1, "subject": "Memory & Amnesia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Confabulation = unintentionally filling memory gaps with plausible but false accounts, with no intent to deceive — seen in Korsakoff and frontal damage.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Perseveration is repeating a response.</li><li><b>C —</b> Delusion is a fixed false belief, not a memory gap-filler.</li><li><b>D —</b> Paramnesia is a broader memory-distortion term.</li></ul><div class=\"ex-sub\">Remember</div><p>Confabulation = honest &#x27;gap-filling&#x27; with false memories (not lying).</p>", "examWatch": "As per PsychLogic's analysis: Confabulation (honest gap-filling) vs lying vs delusion is a fine distinction examiners like — tie it to Korsakoff."}, {"id": 60, "question": "Acetylcholine is particularly important in:", "options": ["Neuromuscular transmission and memory", "Visual processing only", "Regulation of blood glucose only", "Spinal reflexes only"], "correctAnswer": 0, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Acetylcholine is the transmitter at the neuromuscular junction (muscle activation) and is central to attention, learning and memory; its loss features in Alzheimer&#x27;s.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Not vision-only.</li><li><b>C —</b> Glucose is insulin&#x27;s job.</li><li><b>D —</b> Not spinal-reflex-only.</li></ul><div class=\"ex-sub\">Remember</div><p>ACh = neuromuscular junction + memory/attention (Alzheimer&#x27;s).</p>", "examWatch": "As per PsychLogic's analysis: Acetylcholine&#x27;s dual role (neuromuscular junction + memory, Alzheimer&#x27;s) is high-yield — know both."}, {"id": 61, "question": "A patient can recall childhood events but cannot form new long-term memories after bilateral medial temporal damage. This is:", "options": ["Retrograde amnesia", "Anterograde amnesia", "Dissociative amnesia", "Procedural amnesia"], "correctAnswer": 1, "subject": "Memory & Amnesia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Anterograde amnesia = inability to form NEW long-term memories after injury, while older memories survive — typical of bilateral medial temporal (hippocampal) damage.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Retrograde = losing OLD memories.</li><li><b>C —</b> Dissociative amnesia is psychological, not from this lesion.</li><li><b>D —</b> &#x27;Procedural amnesia&#x27; isn&#x27;t the standard term here.</li></ul><div class=\"ex-sub\">Remember</div><p>Anterograde = can&#x27;t make new memories; retrograde = lose old ones.</p>", "examWatch": "As per PsychLogic's analysis: Anterograde vs retrograde amnesia is a guaranteed distinction — &#x27;new vs old memories&#x27; is the one-line answer."}, {"id": 62, "question": "Korsakoff syndrome is classically associated with deficiency of:", "options": ["Vitamin C", "Thiamine (vitamin B1)", "Vitamin D", "Vitamin K"], "correctAnswer": 1, "subject": "Memory & Amnesia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Korsakoff syndrome comes from thiamine (vitamin B1) deficiency, usually with chronic alcohol use — causing severe anterograde amnesia and confabulation.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Vitamin C deficiency = scurvy.</li><li><b>C —</b> Vitamin D = bone/calcium.</li><li><b>D —</b> Vitamin K = clotting.</li></ul><div class=\"ex-sub\">Remember</div><p>Korsakoff = thiamine (B1) deficiency (often alcohol-related).</p>", "examWatch": "As per PsychLogic's analysis: Korsakoff = thiamine (B1) deficiency is a must-know, usually alcohol-linked — pair it with confabulation."}, {"id": 63, "question": "Dissociative disorders primarily involve disturbances in:", "options": ["Memory, consciousness, identity, or perception", "Motor coordination only", "Visual acuity only", "Endocrine secretion only"], "correctAnswer": 0, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Dissociative disorders disrupt the normally integrated functions of memory, consciousness, identity and perception — e.g., dissociative amnesia, DID, depersonalization/derealization.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Not motor-only.</li><li><b>C —</b> Not visual-acuity-only.</li><li><b>D —</b> Not endocrine.</li></ul><div class=\"ex-sub\">Remember</div><p>Dissociation = breakdown in integration of memory, identity, consciousness, perception.</p>", "examWatch": "As per PsychLogic's analysis: The definition of dissociation (disrupted integration of memory, identity, consciousness, perception) frames the whole chapter — learn it verbatim."}, {"id": 64, "question": "Match List I (Test) with List II (Primary function assessed):<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Trail Making Test – Part B</td><td>a. Visuospatial construction and visual memory</td></tr><tr><td>2. Stroop Colour–Word Test</td><td>b. Selective attention and response inhibition</td></tr><tr><td>3. Rey–Osterrieth Complex Figure</td><td>c. Set-shifting and visual scanning</td></tr><tr><td>4. Digit Span Backward</td><td>d. Working memory (mental manipulation)</td></tr></tbody></table></div>", "options": ["1-b, 2-c, 3-a, 4-d", "1-c, 2-b, 3-d, 4-a", "1-c, 2-b, 3-a, 4-d", "1-a, 2-b, 3-c, 4-d"], "correctAnswer": 2, "subject": "Assessment & Neuroimaging", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Trail Making B → set-shifting + visual scanning (c); Stroop → selective attention + inhibition (b); Rey–Osterrieth → visuospatial construction + visual memory (a); Digit Span Backward → working memory (d) → 1-c, 2-b, 3-a, 4-d.</p><div class=\"ex-sub\">Remember</div><p>TMT-B (shifting), Stroop (inhibition), Rey figure (visuoconstruction), Digit Span Backward (working memory).</p>", "examWatch": "As per PsychLogic's analysis: Neuropsychological test ↔ function mappings (TMT-B, Stroop, Rey figure, Digit Span) are heavily tested as match items."}, {"id": 65, "question": "Wernicke&#x27;s area is primarily associated with:", "options": ["Speech production", "Language comprehension", "Balance and coordination", "Voluntary movement"], "correctAnswer": 1, "subject": "Language & Aphasia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Wernicke&#x27;s area (posterior superior temporal) supports language comprehension; damage gives fluent but meaningless speech with poor understanding.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Speech production is Broca&#x27;s.</li><li><b>C —</b> Balance/coordination is cerebellar.</li><li><b>D —</b> Voluntary movement is motor cortex.</li></ul><div class=\"ex-sub\">Remember</div><p>Wernicke = comprehension (fluent but empty speech when damaged).</p>", "examWatch": "As per PsychLogic's analysis: Wernicke = comprehension is the partner fact to Broca = production — expect both in the same paper."}, {"id": 66, "question": "A person can see an object but cannot identify what the object is. This may indicate:", "options": ["Agnosia", "Apraxia", "Aphasia", "Ataxia"], "correctAnswer": 0, "subject": "Perception & Agnosias", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Agnosia is failure to recognise a stimulus despite intact sensation — e.g., visual agnosia: you see the object but can&#x27;t identify it.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Apraxia is impaired skilled movement.</li><li><b>C —</b> Aphasia is a language disorder.</li><li><b>D —</b> Ataxia is incoordination.</li></ul><div class=\"ex-sub\">Remember</div><p>Agnosia = &#x27;seeing but not knowing&#x27; (recognition failure with intact senses).</p>", "examWatch": "As per PsychLogic's analysis: The aphasia/apraxia/agnosia/ataxia quartet (&#x27;the four A&#x27;s&#x27;) is classic — one-line definitions prevent mix-ups."}, {"id": 67, "question": "Approximate answers to simple questions, such as “2 + 2 = 5,” are characteristic of:", "options": ["Ganser syndrome", "Cotard syndrome", "Capgras syndrome", "Korsakoff syndrome"], "correctAnswer": 0, "subject": "Named Clinical Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Ganser syndrome features approximate answers (&#x27;2+2=5&#x27;) — near-miss responses — traditionally described in dissociative/factitious presentations.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Cotard = nihilistic delusion.</li><li><b>C —</b> Capgras = impostor delusion.</li><li><b>D —</b> Korsakoff = amnesia/confabulation.</li></ul><div class=\"ex-sub\">Remember</div><p>Ganser = approximate (&#x27;near-miss&#x27;) answers.</p>", "examWatch": "As per PsychLogic's analysis: Ganser&#x27;s &#x27;approximate answers&#x27; is a memorable named sign — keep it distinct from Cotard and Capgras."}, {"id": 68, "question": "A patient repeatedly hears a voice describing their actions in the third person. This is:", "options": ["Thought insertion", "Third-person auditory hallucination", "Thought broadcasting", "Second-person hallucination"], "correctAnswer": 1, "subject": "Descriptive Psychopathology & Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> A voice describing the person&#x27;s actions in the third person (&#x27;he is now standing up&#x27;) is a classic third-person auditory hallucination — one of Schneider&#x27;s first-rank symptoms.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Thought insertion is a passivity phenomenon, not a voice.</li><li><b>C —</b> Thought broadcasting = thoughts leaking out to others.</li><li><b>D —</b> Second-person voices talk TO the person (&#x27;you should…&#x27;).</li></ul><div class=\"ex-sub\">Remember</div><p>Running commentary in the third person = first-rank auditory hallucination.</p>", "examWatch": "As per PsychLogic's analysis: Third-person &#x27;running commentary&#x27; voices are a first-rank symptom — this links back to the Schneider question set."}, {"id": 69, "question": "Match the following: Disorders and Associated Clinical Features<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>Column I</th><th>Column II</th></tr></thead><tbody><tr><td>1. Selective mutism</td><td>a. Excessively familiar behavior with unfamiliar adults</td></tr><tr><td>2. Reactive attachment disorder</td><td>b. Repeated regurgitation of food</td></tr><tr><td>3. Disinhibited social engagement disorder</td><td>c. Reduced/inhibited attachment behavior</td></tr><tr><td>4. Rumination disorder</td><td>d. Failure to speak in specific social situations</td></tr></tbody></table></div>", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-b, 2-a, 3-d, 4-c", "1-a, 2-b, 3-c, 4-d"], "correctAnswer": 1, "subject": "Neurodevelopmental & Genetic", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Selective mutism → failure to speak in specific situations (d); Reactive attachment disorder → inhibited/reduced attachment (c); Disinhibited social engagement → over-familiarity with strangers (a); Rumination disorder → repeated regurgitation (b) → 1-d, 2-c, 3-a, 4-b.</p><div class=\"ex-sub\">Remember</div><p>Selective mutism (won&#x27;t speak), RAD (withdrawn), DSED (over-familiar), rumination (regurgitation).</p>", "examWatch": "As per PsychLogic's analysis: Early-childhood disorders (selective mutism, RAD, DSED, rumination) form a testable match cluster — one feature each."}, {"id": 70, "question": "Pick bodies (tau-positive inclusions) are characteristic of:", "options": ["Frontotemporal dementia", "Dementia with Lewy bodies", "Alzheimer's disease", "Creutzfeldt–Jakob disease"], "correctAnswer": 0, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Pick bodies — tau-positive inclusions — are the hallmark of Pick disease, a frontotemporal dementia presenting with early personality, behaviour and language change.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Lewy body dementia has alpha-synuclein Lewy bodies.</li><li><b>C —</b> Alzheimer&#x27;s has amyloid plaques and tau tangles.</li><li><b>D —</b> Creutzfeldt–Jakob is a prion disease.</li></ul><div class=\"ex-sub\">Remember</div><p>Pick bodies (tau) → frontotemporal dementia.</p>", "examWatch": "As per PsychLogic's analysis: Dementia neuropathology pairings (Pick bodies/tau, Lewy bodies, plaques/tangles, prions) are high-yield — build the table."}, {"id": 71, "question": "A person spends several hours each day worrying that a minor facial feature is severely unattractive, despite being told that the perceived defect is not noticeable. Which diagnosis is most consistent with this presentation?", "options": ["Illness Anxiety Disorder", "Body Dysmorphic Disorder", "Somatic Symptom Disorder", "Social Anxiety Disorder"], "correctAnswer": 1, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Body dysmorphic disorder = hours of preoccupation with a minor/unobservable physical flaw, plus checking, grooming and reassurance-seeking.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Illness anxiety = fear of having a serious disease.</li><li><b>C —</b> Somatic symptom disorder = distress about real symptoms.</li><li><b>D —</b> Social anxiety = fear of negative evaluation.</li></ul><div class=\"ex-sub\">Remember</div><p>BDD = preoccupation with a perceived appearance defect (OCD-related).</p>", "examWatch": "As per PsychLogic's analysis: Body dysmorphic disorder sits in the OCD-related chapter — distinguish it from illness anxiety and somatic symptom disorder."}, {"id": 72, "question": "Excessive worry about multiple areas of life occurring more days than not over an extended period is characteristic of:", "options": ["Panic Disorder", "Specific Phobia", "Generalized Anxiety Disorder", "Separation Anxiety Disorder"], "correctAnswer": 2, "subject": "Mood, Anxiety & Dissociative", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Generalized anxiety disorder = excessive, hard-to-control worry about many areas, more days than not for ≥6 months, with restlessness, fatigue and tension.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Panic disorder = recurrent unexpected panic attacks.</li><li><b>B —</b> Specific phobia = fear of one object/situation.</li><li><b>D —</b> Separation anxiety = fear of separation from attachment figures.</li></ul><div class=\"ex-sub\">Remember</div><p>GAD = chronic, free-floating worry across domains (≥6 months).</p>", "examWatch": "As per PsychLogic's analysis: GAD&#x27;s &#x27;excessive worry, more days than not, ≥6 months&#x27; definition is a reliable fact — note the duration."}, {"id": 73, "question": "The BOLD signal used in functional MRI depends on:", "options": ["Electrical potentials recorded at the scalp", "X-ray attenuation by brain tissue", "Changes in the ratio of oxygenated to deoxygenated haemoglobin", "Positron emission from injected radiotracers"], "correctAnswer": 2, "subject": "Assessment & Neuroimaging", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> The fMRI BOLD signal depends on the ratio of oxygenated to deoxygenated haemoglobin — neural activity changes local blood flow and oxygenation, altering magnetic signal.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Scalp potentials describe EEG.</li><li><b>B —</b> X-ray attenuation describes CT.</li><li><b>D —</b> Positron emission describes PET.</li></ul><div class=\"ex-sub\">Remember</div><p>BOLD = Blood-Oxygen-Level-Dependent signal (oxy/deoxy-haemoglobin ratio).</p>", "examWatch": "As per PsychLogic's analysis: The fMRI BOLD mechanism (oxy/deoxy-haemoglobin) is a favourite &#x27;how does it work&#x27; item — contrast with EEG/PET/CT."}, {"id": 74, "question": "Arrange the stages in the order in which they typically appear in the first sleep cycle of the night: REM sleep N3 (slow-wave sleep) N1 N2", "options": ["3-2-4-1", "3-4-2-1", "4-3-2-1", "3-4-1-2"], "correctAnswer": 1, "subject": "Sleep & Circadian", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> The first sleep cycle goes N1 → N2 → N3 (slow-wave) → REM, i.e., 3-4-2-1 given the list order (N1=3, N2=4, N3=2, REM=1).</p><div class=\"ex-sub\">Remember</div><p>First cycle: N1 → N2 → N3 → REM (REM comes last).</p>", "examWatch": "As per PsychLogic's analysis: Sleep-stage ordering (N1→N2→N3→REM) is a classic sequence item — remember REM comes last in the first cycle."}, {"id": 75, "question": "Benzodiazepines enhance GABA-A receptor function by:", "options": ["Increasing the duration of chloride-channel opening", "Opening the channel directly in the absence of GABA", "Increasing the frequency of chloride-channel opening", "Blocking GABA reuptake"], "correctAnswer": 2, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Benzodiazepines are positive allosteric modulators at GABA-A: with GABA present, they increase the FREQUENCY of chloride-channel opening (barbiturates increase the DURATION).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Increasing duration describes barbiturates.</li><li><b>B —</b> They need GABA present; they don&#x27;t open the channel alone.</li><li><b>D —</b> They don&#x27;t block GABA reuptake.</li></ul><div class=\"ex-sub\">Remember</div><p>Benzodiazepines → ↑ frequency of Cl⁻ channel opening; barbiturates → ↑ duration.</p>", "examWatch": "As per PsychLogic's analysis: Benzodiazepine (frequency) vs barbiturate (duration) action on GABA-A chloride channels is a precise, examinable contrast."}, {"id": 76, "question": "Which description best fits Tourette&#x27;s disorder?", "options": ["A single motor tic or vocal tic persisting for more than 1 year", "Motor and/or vocal tics present for less than 1 year", "Tics beginning after age 18 with stereotypies", "Multiple motor tics and at least one vocal tic, present for more than 1 year, onset before age 18"], "correctAnswer": 3, "subject": "Neurodevelopmental & Genetic", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> Tourette&#x27;s disorder = multiple motor tics AND at least one vocal tic (not necessarily together), lasting &gt;1 year, with onset before age 18.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> A single tic type is persistent (chronic) tic disorder.</li><li><b>B —</b> &lt;1 year is provisional tic disorder.</li><li><b>C —</b> Onset after 18 doesn&#x27;t fit.</li></ul><div class=\"ex-sub\">Remember</div><p>Tourette = multiple motor + ≥1 vocal tic, &gt;1 year, onset &lt;18.</p>", "examWatch": "As per PsychLogic's analysis: Tourette&#x27;s criteria (multiple motor + ≥1 vocal tic, &gt;1 year, onset &lt;18) are tested exactly — know the numbers."}, {"id": 77, "question": "Dialectical behaviour therapy for borderline personality disorder was developed by:", "options": ["Aaron Beck", "Marsha Linehan", "Otto Kernberg", "Jeffrey Young"], "correctAnswer": 1, "subject": "History & Pioneers", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Dialectical behaviour therapy (DBT) for borderline personality disorder was developed by Marsha Linehan, blending mindfulness, distress tolerance, emotion regulation and interpersonal effectiveness.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Beck developed cognitive therapy.</li><li><b>C —</b> Kernberg → transference-focused psychotherapy.</li><li><b>D —</b> Young → schema therapy.</li></ul><div class=\"ex-sub\">Remember</div><p>DBT = Marsha Linehan (for BPD).</p>", "examWatch": "As per PsychLogic's analysis: Therapy–founder pairings (DBT–Linehan, CT–Beck, TFP–Kernberg, schema–Young) recur — this is a quick, high-value set."}, {"id": 78, "question": "Kayser–Fleischer rings are typical of:", "options": ["Tay–Sachs disease", "Neurofibromatosis", "Wilson's disease", "Phenylketonuria"], "correctAnswer": 2, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Kayser–Fleischer rings (copper deposits in the cornea) are typical of Wilson&#x27;s disease, a disorder of copper metabolism with hepatic, neurological and psychiatric features.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Tay–Sachs → cherry-red macular spot.</li><li><b>B —</b> Neurofibromatosis → café-au-lait spots, neurofibromas.</li><li><b>D —</b> PKU → phenylalanine buildup, treated by diet.</li></ul><div class=\"ex-sub\">Remember</div><p>Kayser–Fleischer rings = Wilson&#x27;s disease (copper).</p>", "examWatch": "As per PsychLogic's analysis: Kayser–Fleischer rings → Wilson&#x27;s disease is a memorable eponymous sign — pair it with copper metabolism."}, {"id": 79, "question": "In a split-brain patient, a picture of a key is flashed briefly to the LEFT visual field. The patient is most likely to:", "options": ["Name the key but be unable to pick it out by touch", "Neither name nor retrieve the key", "Name the key and pick it out with the right hand", "Say nothing was seen, but retrieve the key with the left hand"], "correctAnswer": 3, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> A key flashed to the LEFT visual field goes to the RIGHT hemisphere, which can&#x27;t speak — so the split-brain patient says they saw nothing, yet the right hemisphere guides the LEFT hand to pick out the key.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> The left hand (right hemisphere) CAN retrieve it; naming by touch isn&#x27;t the issue.</li><li><b>B —</b> The right hemisphere can still retrieve it.</li><li><b>C —</b> Naming and right-hand retrieval would need the left hemisphere, which didn&#x27;t get the image.</li></ul><div class=\"ex-sub\">Remember</div><p>Left visual field → right hemisphere (mute) → can&#x27;t name, but LEFT hand retrieves.</p>", "examWatch": "As per PsychLogic's analysis: Split-brain visual-field logic (left field → right hemisphere → can&#x27;t name, left hand retrieves) is a reasoning favourite — practise the chain."}, {"id": 80, "question": "The “all-or-none principle” of action potentials means that:", "options": ["A neuron releases every neurotransmitter at the same time", "Stronger stimuli produce larger action potentials", "An action potential either occurs fully after threshold is reached or does not occur", "A neuron can fire only once in its lifetime"], "correctAnswer": 2, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> The all-or-none principle: once threshold is reached, an action potential fires at full, fixed amplitude; stronger stimuli change firing FREQUENCY, not spike size.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Neurotransmitter release isn&#x27;t &#x27;all at once&#x27;.</li><li><b>B —</b> Stronger stimuli don&#x27;t make bigger spikes.</li><li><b>D —</b> Neurons fire repeatedly, not once in a lifetime.</li></ul><div class=\"ex-sub\">Remember</div><p>All-or-none: fixed-size spike above threshold; intensity is coded by frequency.</p>", "examWatch": "As per PsychLogic's analysis: The all-or-none principle and frequency coding is foundational neurophysiology — expect it as a concept check."}, {"id": 81, "question": "After resection of an orbitofrontal meningioma, a 45-year-old accountant becomes tactless, tells crude jokes and spends impulsively, yet scores normally on IQ and memory tests. This pattern is most typical of:", "options": ["Dorsolateral prefrontal (dysexecutive) syndrome", "Medial frontal (akinetic) syndrome", "Anterior temporal syndrome", "Orbitofrontal (disinhibited) syndrome"], "correctAnswer": 3, "subject": "Frontal & Lesion Syndromes", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> Orbitofrontal (disinhibited) syndrome: tactlessness, crude jokes, impulsivity and reckless spending, while IQ and memory tests stay normal — real-world judgement is impaired more than test scores.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Dorsolateral (dysexecutive) syndrome shows poor planning/working memory on testing.</li><li><b>B —</b> Medial frontal (akinetic) syndrome shows apathy/reduced drive.</li><li><b>C —</b> Anterior temporal syndrome affects semantic memory/behaviour differently.</li></ul><div class=\"ex-sub\">Remember</div><p>Orbitofrontal damage = disinhibition (tactless, impulsive) with normal IQ/memory.</p>", "examWatch": "As per PsychLogic's analysis: Frontal-lobe syndromes (orbitofrontal/disinhibited, dorsolateral/dysexecutive, medial/akinetic) are high-yield — match the behaviour to the region."}, {"id": 82, "question": "The Go/No-Go test is most commonly used to assess the functioning of which part of the brain?", "options": ["Occipital lobe", "Temporal lobe", "Frontal lobe", "Cerebellum"], "correctAnswer": 2, "subject": "Attention & Executive Function", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> The Go/No-Go task measures response inhibition (withholding a prepotent response), a frontal-lobe (inferior frontal/frontostriatal) function.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Occipital = vision.</li><li><b>B —</b> Temporal = memory/auditory.</li><li><b>D —</b> Cerebellum = coordination.</li></ul><div class=\"ex-sub\">Remember</div><p>Go/No-Go = response inhibition → frontal lobe.</p>", "examWatch": "As per PsychLogic's analysis: The Go/No-Go task ↔ frontal response inhibition is a standard test–function link."}, {"id": 83, "question": "In this test the examinee copies nine geometric designs, one at a time, from cards; it is widely used to screen visuomotor integration and organic dysfunction. It is the:", "options": ["Benton Visual Retention Test", "Bender Visual Motor Gestalt Test", "Rey–Osterrieth Complex Figure", "Clock Drawing Test"], "correctAnswer": 1, "subject": "Assessment & Neuroimaging", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> The Bender Visual Motor Gestalt Test asks the examinee to copy nine geometric designs, screening visuomotor integration and possible organic dysfunction.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Benton Visual Retention Test stresses visual memory.</li><li><b>C —</b> Rey–Osterrieth uses one complex figure.</li><li><b>D —</b> Clock Drawing is a brief screen.</li></ul><div class=\"ex-sub\">Remember</div><p>Bender-Gestalt = copy 9 designs → visuomotor integration.</p>", "examWatch": "As per PsychLogic's analysis: The Bender-Gestalt (nine designs, visuomotor integration) is a frequently named test — know what it screens."}, {"id": 84, "question": "Which Halstead–Reitan subtest chiefly assesses abstraction and concept formation?", "options": ["Tactual Performance Test", "Category Test", "Seashore Rhythm Test", "Finger Oscillation (Tapping) Test"], "correctAnswer": 1, "subject": "Assessment & Neuroimaging", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> The Halstead–Reitan Category Test assesses abstraction and concept formation — figuring out classification rules from feedback — and is sensitive to broad brain dysfunction.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Tactual Performance Test → tactile/spatial learning.</li><li><b>C —</b> Seashore Rhythm Test → auditory attention.</li><li><b>D —</b> Finger Tapping → motor speed.</li></ul><div class=\"ex-sub\">Remember</div><p>Category Test = abstraction/concept formation (Halstead–Reitan).</p>", "examWatch": "As per PsychLogic's analysis: Halstead–Reitan subtests appear as match/identify items — Category Test = abstraction is the key one."}, {"id": 85, "question": "The Hachinski Ischemic Score is used to distinguish:", "options": ["Delirium from dementia", "Vascular dementia from degenerative dementia", "Schizophrenia from mania", "Epileptic from non-epileptic seizures"], "correctAnswer": 1, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> The Hachinski Ischemic Score uses features like abrupt onset, stepwise decline and focal signs to distinguish vascular dementia from degenerative (e.g., Alzheimer&#x27;s) dementia.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Delirium vs dementia uses other tools (e.g., CAM).</li><li><b>C —</b> Not for schizophrenia vs mania.</li><li><b>D —</b> Not for seizure classification.</li></ul><div class=\"ex-sub\">Remember</div><p>Hachinski score = vascular vs degenerative dementia.</p>", "examWatch": "As per PsychLogic's analysis: The Hachinski Ischemic Score (vascular vs degenerative dementia) is a named instrument worth recognising."}, {"id": 86, "question": "A 72-year-old has fluctuating alertness, well-formed visual hallucinations of children in the room, mild parkinsonism, and severe rigidity after a low dose of haloperidol. The most likely diagnosis is:", "options": ["Alzheimer's disease", "Vascular dementia", "Dementia with Lewy bodies", "Frontotemporal dementia"], "correctAnswer": 2, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Dementia with Lewy bodies: fluctuating cognition, recurrent well-formed visual hallucinations, spontaneous parkinsonism, and severe antipsychotic (neuroleptic) sensitivity — rigidity after low-dose haloperidol is a red flag.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Alzheimer&#x27;s = gradual memory-led decline, no early hallucinations/parkinsonism.</li><li><b>B —</b> Vascular = stepwise, vascular signs.</li><li><b>D —</b> Frontotemporal = early behaviour/personality change.</li></ul><div class=\"ex-sub\">Remember</div><p>DLB = fluctuations + visual hallucinations + parkinsonism + neuroleptic sensitivity.</p>", "examWatch": "As per PsychLogic's analysis: Dementia-with-Lewy-bodies features (fluctuation, visual hallucinations, parkinsonism, neuroleptic sensitivity) make a classic vignette — learn the tetrad."}, {"id": 87, "question": "A patient has non-fluent, reduced spontaneous speech and difficulty initiating conversation, but is able to understand language and repeat spoken words or sentences accurately. Which type of aphasia is most likely present?", "options": ["Broca’s aphasia", "Wernicke’s aphasia", "Conduction aphasia", "Transcortical motor aphasia"], "correctAnswer": 3, "subject": "Language & Aphasia", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> Transcortical motor aphasia: non-fluent, hard-to-initiate speech BUT comprehension AND repetition are preserved (the perisylvian core is intact, so repetition survives).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Broca&#x27;s aphasia impairs repetition.</li><li><b>B —</b> Wernicke&#x27;s impairs comprehension.</li><li><b>C —</b> Conduction aphasia has fluent speech but impaired repetition.</li></ul><div class=\"ex-sub\">Remember</div><p>Transcortical motor = non-fluent but repetition intact (vs Broca&#x27;s, where repetition fails).</p>", "examWatch": "As per PsychLogic's analysis: Transcortical motor aphasia (repetition preserved) is the subtle contrast to Broca&#x27;s — repetition is the discriminator."}, {"id": 88, "question": "The classical triad of normal pressure hydrocephalus is:", "options": ["Ophthalmoplegia, ataxia, confusion", "Tremor, rigidity, bradykinesia", "Gait disturbance, urinary incontinence, cognitive decline", "Chorea, dementia, depression"], "correctAnswer": 2, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (C) is correct:</b> Normal-pressure hydrocephalus triad: gait disturbance (magnetic gait), urinary incontinence, and cognitive decline — &#x27;wet, wobbly, wacky&#x27;.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Ophthalmoplegia/ataxia/confusion = Wernicke&#x27;s encephalopathy.</li><li><b>B —</b> Tremor/rigidity/bradykinesia = parkinsonism.</li><li><b>D —</b> Chorea/dementia/depression = Huntington&#x27;s.</li></ul><div class=\"ex-sub\">Remember</div><p>NPH triad = gait + incontinence + cognition (&#x27;wet, wobbly, wacky&#x27;).</p>", "examWatch": "As per PsychLogic's analysis: The NPH triad (&#x27;wet, wobbly, wacky&#x27;) is a memorable, examinable set — learn the mnemonic."}, {"id": 89, "question": "A man&#x27;s hand tremor worsens as it approaches a glass; he overshoots the target, cannot perform rapid alternating hand movements, and walks with a wide-based gait. The lesion is in the:", "options": ["Caudate nucleus", "Substantia nigra", "Primary motor cortex", "Cerebellum"], "correctAnswer": 3, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> Intention tremor (worse near a target), overshooting (dysmetria), impaired rapid alternating movements (dysdiadochokinesia) and a wide-based gait all point to the cerebellum.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Caudate → chorea (Huntington&#x27;s).</li><li><b>B —</b> Substantia nigra → Parkinson&#x27;s.</li><li><b>C —</b> Primary motor cortex → weakness/paralysis.</li></ul><div class=\"ex-sub\">Remember</div><p>Cerebellar signs: intention tremor, dysmetria, dysdiadochokinesia, wide-based gait.</p>", "examWatch": "As per PsychLogic's analysis: Cerebellar signs (intention tremor, dysmetria, dysdiadochokinesia, wide gait) are a reliable localisation cluster."}, {"id": 90, "question": "compared with dementia, depressive pseudodementia typically shows:", "options": ["Frequent \"I don't know\" answers with complaints of memory loss", "\"Near-miss\" answers and unawareness of deficits", "Prominent confabulation", "Gradual onset with steady progression"], "correctAnswer": 0, "subject": "Dementias & Movement Disorders", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Depressive pseudodementia typically shows prominent complaints of memory loss and frequent &#x27;I don&#x27;t know&#x27; answers (low effort), unlike true dementia where patients often downplay deficits.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> &#x27;Near-miss&#x27; answers + unawareness fit organic dementia.</li><li><b>C —</b> Prominent confabulation suggests Korsakoff.</li><li><b>D —</b> Gradual, steadily progressive onset fits neurodegeneration.</li></ul><div class=\"ex-sub\">Remember</div><p>Pseudodementia: complains a lot, says &#x27;I don&#x27;t know&#x27;; dementia: tries but is unaware of deficits.</p>", "examWatch": "As per PsychLogic's analysis: Pseudodementia vs true dementia (&#x27;I don&#x27;t know&#x27; vs near-miss/unaware) is a classic differential — learn the behavioural contrast."}, {"id": 91, "question": "In dichotic listening with verbal stimuli, most right-handed people show a right-ear advantage. This reflects:", "options": ["Crossed auditory pathways dominating, with left-hemisphere language specialization", "Right-hemisphere dominance for speech", "Better peripheral hearing in the right ear", "Dominance of ipsilateral auditory pathways"], "correctAnswer": 0, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> The right-ear advantage for verbal dichotic listening reflects left-hemisphere language dominance plus stronger crossed (contralateral) auditory pathways carrying the right ear to the left hemisphere.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Speech is left-, not right-, dominant in most people.</li><li><b>C —</b> It&#x27;s not better peripheral hearing.</li><li><b>D —</b> Contralateral, not ipsilateral, pathways dominate.</li></ul><div class=\"ex-sub\">Remember</div><p>Right-ear advantage = left-hemisphere language + crossed auditory pathways.</p>", "examWatch": "As per PsychLogic's analysis: The right-ear advantage in dichotic listening tests lateralisation reasoning — tie it to left-hemisphere language."}, {"id": 92, "question": "Which of the following is a major function of oxytocin?", "options": ["Regulation of the sleep–wake cycle", "Facilitation of social bonding, uterine contractions, and milk ejection", "Control of voluntary skeletal-muscle movement", "Regulation of blood glucose levels"], "correctAnswer": 1, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Oxytocin drives uterine contractions in labour and milk ejection (let-down) in breastfeeding, and supports social bonding and affiliation.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Sleep–wake is melatonin/SCN.</li><li><b>C —</b> Voluntary movement is motor system.</li><li><b>D —</b> Glucose is insulin.</li></ul><div class=\"ex-sub\">Remember</div><p>Oxytocin = bonding + uterine contractions + milk ejection.</p>", "examWatch": "As per PsychLogic's analysis: Oxytocin&#x27;s functions (bonding, uterine contraction, milk ejection) are a compact, testable set."}, {"id": 93, "question": "DSM-5 requires that several ADHD symptoms be present before the age of:", "options": ["7 years", "12 years", "5 years", "18 years"], "correctAnswer": 1, "subject": "Neurodevelopmental & Genetic", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> DSM-5 requires several ADHD symptoms to be present before age 12 (raised from the old age-7 threshold).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Age 7 was the old DSM-IV threshold.</li><li><b>C —</b> Age 5 is too early.</li><li><b>D —</b> Age 18 is too late.</li></ul><div class=\"ex-sub\">Remember</div><p>ADHD: several symptoms before age 12 (DSM-5).</p>", "examWatch": "As per PsychLogic's analysis: ADHD&#x27;s &#x27;symptoms before age 12&#x27; (DSM-5) is a precise number examiners target — note it changed from age 7."}, {"id": 94, "question": "The term &quot;schizophrenia&quot; was coined in 1908 by:", "options": ["Eugen Bleuler", "Emil Kraepelin", "Kurt Schneider", "Benedict Morel"], "correctAnswer": 0, "subject": "History & Pioneers", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> Eugen Bleuler coined &#x27;schizophrenia&#x27; in 1908, stressing splitting/loosening between thought, emotion and behaviour (his &#x27;4 A&#x27;s&#x27;).</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Kraepelin described &#x27;dementia praecox&#x27; earlier.</li><li><b>C —</b> Schneider gave first-rank symptoms.</li><li><b>D —</b> Morel used &#x27;démence précoce&#x27; earlier still.</li></ul><div class=\"ex-sub\">Remember</div><p>Bleuler (1908) coined &#x27;schizophrenia&#x27;; Kraepelin = dementia praecox.</p>", "examWatch": "As per PsychLogic's analysis: Bleuler (1908, &#x27;schizophrenia&#x27;) vs Kraepelin (dementia praecox) vs Schneider (first-rank) is a history trio worth fixing."}, {"id": 95, "question": "Match List I (Pioneer) with List II (Treatment introduced):<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Julius Wagner-Jauregg</td><td>a. Prefrontal leucotomy</td></tr><tr><td>2. Cerletti and Bini</td><td>b. Insulin coma therapy</td></tr><tr><td>3. Egas Moniz</td><td>c. Malarial fever therapy for general paresis</td></tr><tr><td>4. Manfred Sakel</td><td>d. Electroconvulsive therapy</td></tr></tbody></table></div>", "options": ["1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a", "1-b, 2-d, 3-a, 4-c"], "correctAnswer": 1, "subject": "History & Pioneers", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Wagner-Jauregg → malarial fever therapy for general paresis (c); Cerletti &amp; Bini → ECT (d); Egas Moniz → prefrontal leucotomy (a); Manfred Sakel → insulin coma therapy (b) → 1-c, 2-d, 3-a, 4-b.</p><div class=\"ex-sub\">Remember</div><p>Wagner-Jauregg (malaria therapy), Cerletti–Bini (ECT), Moniz (leucotomy), Sakel (insulin coma).</p>", "examWatch": "As per PsychLogic's analysis: Somatic-treatment pioneers (Wagner-Jauregg, Cerletti–Bini, Moniz, Sakel) are a classic history match set."}, {"id": 96, "question": "The idea that the nervous system is hierarchically organized, and that damage produces &quot;dissolution&quot; (release of lower functions), was proposed by:", "options": ["Alexander Luria", "John Hughlings Jackson", "Wilder Penfield", "Henry Head"], "correctAnswer": 1, "subject": "History & Pioneers", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> John Hughlings Jackson proposed that the nervous system is hierarchically organized and that damage causes &#x27;dissolution&#x27; — loss of higher control releasing lower, automatic functions.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Luria developed functional neuropsychology/systems.</li><li><b>C —</b> Penfield mapped the cortex with stimulation.</li><li><b>D —</b> Head studied aphasia and sensation.</li></ul><div class=\"ex-sub\">Remember</div><p>Hughlings Jackson = hierarchy + &#x27;dissolution&#x27; (release of lower functions).</p>", "examWatch": "As per PsychLogic's analysis: Hughlings Jackson&#x27;s hierarchy and &#x27;dissolution&#x27; is a named theory that recurs in history-of-neuropsychology items."}, {"id": 97, "question": "Which of the following brain structures is commonly regarded as a reinforcement center?", "options": ["Basal nucleus", "Basolateral nucleus", "Central nucleus", "Nucleus accumbens"], "correctAnswer": 3, "subject": "Neuroanatomy & Circuits", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (D) is correct:</b> The nucleus accumbens, driven by dopamine from the ventral tegmental area (mesolimbic pathway), is the brain&#x27;s key reward/reinforcement centre.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> Basal nucleus (of Meynert) is cholinergic (memory).</li><li><b>B —</b> Basolateral amygdala → emotional learning.</li><li><b>C —</b> Central amygdala → fear output.</li></ul><div class=\"ex-sub\">Remember</div><p>Nucleus accumbens = reward centre (mesolimbic dopamine).</p>", "examWatch": "As per PsychLogic's analysis: The nucleus accumbens as the mesolimbic reward centre is high-yield for addiction and motivation questions."}, {"id": 98, "question": "According to Jellinek’s typology of alcoholism, deliberate and undisciplined drinking is characteristic of which type of alcoholism?", "options": ["Alpha alcoholism", "Beta alcoholism", "Gamma alcoholism", "Delta alcoholism"], "correctAnswer": 0, "subject": "Substance Use", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> In Jellinek&#x27;s typology, alpha alcoholism is psychologically motivated, undisciplined drinking to relieve distress, WITHOUT the physical dependence of gamma/delta types.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Beta = physical complications without dependence.</li><li><b>C —</b> Gamma = loss of control + physical dependence.</li><li><b>D —</b> Delta = inability to abstain (continuous).</li></ul><div class=\"ex-sub\">Remember</div><p>Jellinek: alpha (psychological), beta (physical harm), gamma (loss of control), delta (can&#x27;t abstain).</p>", "examWatch": "As per PsychLogic's analysis: Jellinek&#x27;s alcoholism typology (alpha–epsilon) is historically important and still examined — know alpha vs gamma/delta."}, {"id": 99, "question": "Glutamate is best described as the:", "options": ["Major inhibitory neurotransmitter in the brain", "Major excitatory neurotransmitter in the brain", "Hormone responsible for milk ejection", "Neurotransmitter responsible only for sleep"], "correctAnswer": 1, "subject": "Neurophysiology & Neurochemistry", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (B) is correct:</b> Glutamate is the brain&#x27;s major EXCITATORY neurotransmitter, central to learning, memory and synaptic plasticity (and excitotoxicity); key receptors are NMDA and AMPA.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>A —</b> GABA is the major inhibitory transmitter.</li><li><b>C —</b> Milk ejection is oxytocin.</li><li><b>D —</b> It&#x27;s not sleep-only.</li></ul><div class=\"ex-sub\">Remember</div><p>Glutamate = main excitatory transmitter; GABA = main inhibitory.</p>", "examWatch": "As per PsychLogic's analysis: Glutamate (excitatory) vs GABA (inhibitory) is the fundamental transmitter pair — a guaranteed concept check."}, {"id": 100, "question": "Which hypothalamic nucleus is most closely associated with regulation of circadian rhythm and the sleep–wake cycle?", "options": ["Suprachiasmatic nucleus", "Caudate nucleus", "Red nucleus", "Substantia nigra"], "correctAnswer": 0, "subject": "Sleep & Circadian", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why (A) is correct:</b> The suprachiasmatic nucleus (SCN) of the hypothalamus is the master circadian clock: it reads retinal light input and sets daily rhythms of sleep, hormones and temperature.</p><div class=\"ex-sub\">Why the other options don't fit</div><ul class=\"ex-list\"><li><b>B —</b> Caudate = movement.</li><li><b>C —</b> Red nucleus = motor coordination.</li><li><b>D —</b> Substantia nigra = dopamine/movement.</li></ul><div class=\"ex-sub\">Remember</div><p>SCN = master circadian pacemaker (sleep–wake clock).</p>", "examWatch": "As per PsychLogic's analysis: The SCN as the master circadian clock is foundational for sleep/rhythm questions — pair it with melatonin and light input."}];
